def solve(inputs, readings):
    event = readings['event']
    attendees = inputs['attendees']

    if event == 'meeting':
        required_seats = attendees
    elif event == 'workshop':
        required_seats = attendees + (attendees + 4) // 5
    else:
        required_seats = attendees

    def decimal_ratio(value):
        text = str(value).lower()
        if 'e' in text:
            mantissa, exponent_text = text.split('e', 1)
            exponent = int(exponent_text)
        else:
            mantissa = text
            exponent = 0
        sign = 1
        if mantissa.startswith('-'):
            sign = -1
            mantissa = mantissa[1:]
        elif mantissa.startswith('+'):
            mantissa = mantissa[1:]
        if '.' in mantissa:
            whole, fractional = mantissa.split('.', 1)
        else:
            whole, fractional = mantissa, ''
        digits = (whole or '0') + fractional
        numerator = sign * int(digits or '0')
        denominator = 10 ** len(fractional)
        if exponent > 0:
            numerator *= 10 ** exponent
        elif exponent < 0:
            denominator *= 10 ** (-exponent)
        return numerator, denominator

    suitable = []
    for room in inputs['rooms']:
        if room['seats'] < required_seats:
            continue
        if event == 'party' and not room['music']:
            continue
        rate_num, rate_den = decimal_ratio(room['rate'])
        suitable.append((rate_num / rate_den, room['seats'], room['name'], rate_num, rate_den))

    if not suitable:
        return event + ': none'

    suitable.sort(key=lambda item: (item[0], item[1], item[2]))
    _, _, name, rate_num, rate_den = suitable[0]
    hours_num, hours_den = decimal_ratio(inputs['hours'])
    cost_num = rate_num * 100 * hours_num
    cost_den = rate_den * hours_den
    if event == 'party':
        cost_num *= 11
        cost_den *= 10
    pennies = (2 * cost_num + cost_den) // (2 * cost_den)
    return event + ': ' + name + ' ' + str(pennies // 100) + '.' + str(pennies % 100).zfill(2)

def solve(inputs, readings):
    item_cents = 0
    for price in inputs['items']:
        pounds, pence = price.split('.')
        item_cents += int(pounds) * 100 + int(pence)

    service = readings['service']
    if service == 'poor':
        tip_cents = 0
    elif service == 'good':
        tip_cents = (item_cents + 4) // 8
    else:
        tip_cents = (item_cents * 3 + 10) // 20

    total_cents = item_cents + tip_cents
    diners = inputs['diners']
    each_cents = (total_cents + diners - 1) // diners
    extra_cents = each_cents * diners - total_cents

    def pounds(cents):
        return str(cents // 100) + '.' + str(cents % 100).zfill(2)

    return 'total ' + pounds(total_cents) + ' | each ' + pounds(each_cents) + ' | extra ' + pounds(extra_cents)

