    if service == 'poor':
        tip = 0
    elif service == 'good':
        tip = (subtotal + 4) // 8
    else:
        tip = (subtotal * 3 + 10) // 20

    total = subtotal + tip
    diners = int(inputs['diners'])
    each = (total + diners - 1) // diners
    extra = each * diners - total

    def format_pounds(pence):
        return str(pence // 100) + '.' + str(pence % 100).zfill(2)

    return 'total ' + format_pounds(total) + ' | each ' + format_pounds(each) + ' | extra ' + format_pounds(extra)
